cd /home/hyphyphyph/piton/repl; python3 - <<'EOF'
p='src/chat_input.rs'
s=open(p).read()
old="""        // A joined chain once selected, and a broken one dimmed to half
        // opacity until then.
        let chain_icon = Icon::new(if unified {
            IconName::Link
        } else {
            IconName::Unlink
        })
        .text_color(if unified {
            cx.theme().tab_active_foreground
        } else {
            cx.theme().tab_foreground.opacity(0.5)
        });"""
new="""        // In Chain's purple, selected or not: a joined chain once selected,
        // and a broken one dimmed to half opacity until then.
        let chain_color = mode_color(SendMode::Both, cx);
        let chain_icon = Icon::new(if unified {
            IconName::Link
        } else {
            IconName::Unlink
        })
        .text_color(if unified {
            chain_color
        } else {
            chain_color.opacity(0.5)
        });"""
assert s.count(old)==1
s=s.replace(old,new)
open(p,'w').write(s)
EOF
cargo build 2>&1 | grep -E "^(error|warning)" -A6 | head; grep -n "tab_active_foreground\|chain.*color\|icon.*colour" src/chat_input.rs | awk -F: '$1>2500' | head

